// One program drives all three options. quote() wins the race instantly;
// transfer() is cancelled while parked in sleep(200), AFTER it has opened a
// ledger and BEFORE its commit. What the cancelled task does at that sleep
// is the whole decision.
use core.tasks as tasks
use core.time as time

fn transfer() -> Int {
    ledger :: open_ledger()   // Drop-backed: prints "ledger closed" on ANY scope exit
    time.sleep(200)           // <-- cancelled here: the race picks quote() first
    ledger.commit()           // prints "committed" — a real, unwanted side effect
    return 500
}

fn quote() -> Int {
    return 7                  // returns immediately, wins the race
}

fn run() {
    taskgroup g {
        t :: g.task(() => transfer())
        q :: g.task(() => quote())
        winner :: g.race([t, q])   // quote wins; transfer is cancelled mid-sleep
        print("winner: {winner}")
    }
    print("group done")
}

